// Build the stage-1 host-service rollout archive for the existing warden Linux Enclave host (work/hosted-services-activation).
//   node build-stage.mjs           -> stage/enclave-host-services-<label>/ + out/enclave-host-services-<label>.tar (+ .sha256)
//   node build-stage.mjs --check   -> rebuild in a temporary directory and require the identical archive bytes
// Inputs (all public; recorded with their sha256 in the archive's STAGE-INPUTS.json):
//   tree/                         isolated copy of main (base/main-tree.sha256) + the runner endpoint fix and the stage
//                                 tool (patches/); the runner and the tool are bundled from it (esbuild, node22)
//   tree/network/host-services/packages/   the four FINAL role packages, required to match the integrated pins
//   ../directory-runtime-activation/hosts/*.facts.json   the fleet directory's public configuration fields
//   ../adapter-retained/manifest.next.json               the bootstrap manifest the four fleet replicas serve
//   root-public-host-facts.json                          root's listener capture of this host (port choice)
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const TREE = path.join(HERE, 'tree'), W = path.resolve(HERE, '..');
const LABEL = 'hs1';
const FINAL_PINS = {   // the integrated packages (work/hosted-service-main-integration/inventory.json)
  'directory-replica': 'sha256:2d69a8be882bea9fc107208a3828e25a773ce0c988eac6347d377904e9e78668',
  'bootstrap-replica': 'sha256:7732950bc2f6385275278553bd36f5372a799f3183b2e26abebadd940414dffc',
  'route-dns': 'sha256:350c276f17a0ea15fc0451c614146554c2b08cf89c9b3258013ac188950d3cf8',
  'policy-mirror': 'sha256:a031723ee86c9bf3a2489936a3c7449a6c72ff9b999902e57644c9fbc773eb41',
};
const BOOTSTRAP_MANIFEST = { file: path.join(W, 'adapter-retained/manifest.next.json'), sha256: '62c4ed1b40f2731be1d6124f81b0dd65c13a4b1626afaa47910e8801ee8d73ca' };
const sha = (b) => createHash('sha256').update(b).digest('hex');
const check = process.argv.includes('--check');
const esbuild = createRequire(path.join(TREE, 'package.json'))('esbuild');

async function bundle(entry, outfile, { ownEntryCheck }) {
  const r = await esbuild.build({ absWorkingDir: TREE, entryPoints: [entry], outfile, write: false, metafile: true, bundle: true, platform: 'node', format: 'esm',
    target: 'node22', legalComments: 'none',
    banner: { js: `// Generated by work/hosted-services-activation/build-stage.mjs from ${entry}; do not edit.\nimport {createRequire as __enclaveStageCreateRequire} from "node:module"; const require=__enclaveStageCreateRequire(import.meta.url);` } });
  const bytes = Buffer.from(r.outputFiles[0].contents);
  const probe = path.join(os.tmpdir(), `stage-probe-${process.pid}-${path.basename(outfile)}`);
  try { fs.writeFileSync(probe, bytes); execFileSync(process.execPath, ['--check', probe], { stdio: ['ignore', 'ignore', 'pipe'] }); }
  catch (e) { throw new Error(`${entry}: the bundle does not parse: ${String(e.stderr || e.message).slice(0, 400)}`); }
  finally { fs.rmSync(probe, { force: true }); }
  const checks = (bytes.toString('utf8').match(/process\.argv\[1\]\s*&&[^\n]{0,200}import\.meta\.url/g) || []).length;
  if (ownEntryCheck && checks !== 1) throw new Error(`${entry}: ${checks} "main module" checks in the bundle; exactly its own is allowed`);
  const inputs = {};
  for (const rel of Object.keys(r.metafile.inputs).sort()) {
    const norm = rel.includes('node_modules/') ? 'node_modules/' + rel.split('node_modules/').pop() : rel;
    inputs[norm] = sha(fs.readFileSync(path.resolve(TREE, rel)));
  }
  return { bytes, inputs, mainChecks: checks };
}

function fleetDirectory() {
  const hosts = ['us-west', 'eu-central', 'ap-southeast', 'ca-east'], facts = {};
  let ref = null;
  for (const h of hosts) {
    const f = path.join(W, `directory-runtime-activation/hosts/${h}.facts.json`), raw = fs.readFileSync(f);
    const c = JSON.parse(raw).configs['/etc/enclave-directory/config-f6959cb.json'];
    const t = JSON.stringify([c.addressBook.toLowerCase(), c.checkers, c.authorityPins, c.rpcOrigins]);
    if (ref && t !== ref) throw new Error(`fleet directory configuration differs on ${h}`);
    ref = t; facts[`work/directory-runtime-activation/hosts/${h}.facts.json`] = sha(raw);
    var cfg = c;
  }
  return { cfg, facts };
}

export async function build(outRoot) {
  const stageName = `enclave-host-services-${LABEL}`, S = path.join(outRoot, 'stage', stageName);
  fs.rmSync(S, { recursive: true, force: true });
  for (const d of ['bin', 'packages', 'config', 'data', 'systemd', 'scripts']) fs.mkdirSync(path.join(S, d), { recursive: true });
  for (const d of ['', 'bin', 'packages', 'config', 'data', 'systemd', 'scripts']) fs.chmodSync(path.join(S, d), 0o755);   // archive modes never depend on umask
  const put = (rel, data, mode = 0o644) => { fs.writeFileSync(path.join(S, rel), data); fs.chmodSync(path.join(S, rel), mode); };
  // packages: exactly the integrated final bytes
  const pkgDir = path.join(TREE, 'network/host-services/packages');
  for (const [role, pin] of Object.entries(FINAL_PINS)) {
    const man = fs.readFileSync(path.join(pkgDir, `${role}.package.json`));
    if ('sha256:' + sha(man) !== pin) throw new Error(`${role}: package manifest is not the final pin ${pin}`);
    const m = JSON.parse(man), b = fs.readFileSync(path.join(pkgDir, m.bundle));
    if (sha(b) !== m.bundleSha256) throw new Error(`${role}: bundle does not match its manifest`);
    put(`packages/${role}.package.json`, man); put(`packages/${m.bundle}`, b);
  }
  // runner + tool, bundled
  const runner = await bundle('network/host-services/runner.mjs', 'host-services-runner.mjs', { ownEntryCheck: true });
  const tool = await bundle('network/host-services/entries/stage-tool.mjs', 'stage-tool.mjs', { ownEntryCheck: false });
  put('bin/host-services-runner.mjs', runner.bytes); put('bin/stage-tool.mjs', tool.bytes);
  // the exact public configuration
  const { cfg: fleet, facts } = fleetDirectory();
  const pinDoc = JSON.parse(fs.readFileSync(path.join(TREE, 'contracts/deployments/service-index-activation-base.json'), 'utf8')).indexPin;
  const NS = ['ns-us-west.enclave.host', 'ns-eu-central.enclave.host', 'ns-ap-southeast.enclave.host', 'ns-ca-east.enclave.host'];
  const spec = {
    endpoint: 'https://api.enclave.host/t/metal0', bind: '127.0.0.1',
    ports: { directory: 18188, bootstrap: 18189, dns: 18153, dnsApi: 18154, policy: 18190 },
    stateRoot: `/var/lib/enclave-host-services/${LABEL}`, dataRoot: `/var/lib/enclave-host-services-data/${LABEL}`, packagesDir: `/opt/enclave-host-services/${LABEL}/packages`,
    serviceIndex: pinDoc, pins: FINAL_PINS,
    directoryRpc: fleet.rpcOrigins, authorityPins: fleet.authorityPins, checkers: fleet.checkers, directoryPeers: fleet.peers.concat(['http://134.199.235.187:8188']).sort(),
    dns: { zone: 'app.enclave.host', ipZone: 'ip.enclave.host', nsName: 'ns-metal0.enclave.host', nsNames: [...NS, 'ns-metal0.enclave.host'] },
    provenance: {
      endpoint: 'outputs/dns-responder-live-registry.json (registry entry hostId 0x4dde6d1b..., operator 0xc9d0835c..., active, block 52839357) and work/hosted-services-activation/root-public-host-facts.json (still active 2026-10-21T05:10Z)',
      directory: 'the fleet directory config-f6959cb.json public fields (identical on all four machines): rpcOrigins, authorityPins, checkers; peers = the four fleet directories',
      dns: 'fleet route-DNS zones (work/rollout-route-dns.py) and NS set (work/control-vm/prepare-dns-front.py); ns-metal0.enclave.host is THIS replica\'s name, not delegated (root decides at S5)',
      ports: 'chosen below the ephemeral range and checked against root-public-host-facts.json listeners (gen-config refuses a port in use)',
      bootstrapManifest: 'work/adapter-retained/manifest.next.json: the 936 objects the four fleet replicas serve (work/complete-retained-serving-verification.log)',
    },
  };
  const { genConfig } = await import(pathToFileURL(path.join(TREE, 'network/host-services/stage-tool.mjs')).href);
  const listeners = JSON.parse(fs.readFileSync(path.join(HERE, 'root-public-host-facts.json'), 'utf8')).listeners.join('\n');
  const config = genConfig(spec, listeners);
  put('config/spec.json', JSON.stringify(spec, null, 2) + '\n');
  put('config/host-services.json', JSON.stringify(config, null, 2) + '\n');
  const manifest = fs.readFileSync(BOOTSTRAP_MANIFEST.file);
  if (sha(manifest) !== BOOTSTRAP_MANIFEST.sha256) throw new Error('bootstrap manifest is not the fleet-served 62c4ed1b...');
  put('data/bootstrap-manifest.json', manifest);
  // unit, scripts, plan (label substituted)
  const sub = (f) => fs.readFileSync(path.join(HERE, f), 'utf8').replaceAll('@LABEL@', LABEL);
  put('systemd/enclave-host-services.service', sub('src/systemd/enclave-host-services.service'));
  for (const f of fs.readdirSync(path.join(HERE, 'src/scripts')).sort()) put(`scripts/${f}`, sub(`src/scripts/${f}`), f === 'common.sh' ? 0o644 : 0o755);
  put('ACTIVATION.txt', sub('src/ACTIVATION.txt'));
  const inputs = { label: LABEL, mainHead: fs.readFileSync(path.join(HERE, 'base/main-head.txt'), 'utf8').trim(), finalPins: FINAL_PINS,
    runnerClosure: runner.inputs, toolClosure: tool.inputs, publicFacts: { ...facts, 'work/adapter-retained/manifest.next.json': BOOTSTRAP_MANIFEST.sha256,
      'work/hosted-services-activation/root-public-host-facts.json': sha(fs.readFileSync(path.join(HERE, 'root-public-host-facts.json'))) } };
  put('STAGE-INPUTS.json', JSON.stringify(inputs, null, 1) + '\n');
  // checksums of every file but itself, then the deterministic archive
  const files = [];
  const walk = (d) => { for (const n of fs.readdirSync(d).sort()) { const p = path.join(d, n); if (fs.statSync(p).isDirectory()) walk(p); else files.push(path.relative(S, p)); } };
  walk(S);
  put('STAGE-SHA256SUMS', files.filter((f) => f !== 'STAGE-SHA256SUMS').map((f) => `${sha(fs.readFileSync(path.join(S, f)))}  ${f}`).join('\n') + '\n');
  const out = path.join(outRoot, 'out'); fs.mkdirSync(out, { recursive: true });
  const tar = path.join(out, `${stageName}.tar`);
  execFileSync('tar', ['--sort=name', '--mtime=@0', '--owner=0', '--group=0', '--numeric-owner', '--format=gnu', '-C', path.join(outRoot, 'stage'), '-cf', tar, stageName]);
  const digest = sha(fs.readFileSync(tar));
  fs.writeFileSync(`${tar}.sha256`, `${digest}  ${path.basename(tar)}\n`);
  return { tar, digest, files: files.length + 1, runnerBytes: runner.bytes.length, toolBytes: tool.bytes.length, runnerInputs: Object.keys(runner.inputs).length, toolInputs: Object.keys(tool.inputs).length };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  if (check) {
    const want = fs.readFileSync(path.join(HERE, `out/enclave-host-services-${LABEL}.tar.sha256`), 'utf8').split(/\s+/)[0];
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'stage-check-'));
    try { const r = await build(tmp); if (r.digest !== want) { console.error(`NOT reproducible: rebuilt ${r.digest}, recorded ${want}`); process.exit(1); } console.log(`reproducible: ${r.digest}`); }
    finally { fs.rmSync(tmp, { recursive: true, force: true }); }
  } else console.log(JSON.stringify(await build(HERE), null, 1));
}
